const i18n = { lang: "en" };

function t(s, vars) {
  let out = i18n.lang === "zh" && Object.prototype.hasOwnProperty.call(ZH, s) ? ZH[s] : s;
  if (vars) out = out.replace(/\{(\w+)\}/g, (m, k) => (Object.prototype.hasOwnProperty.call(vars, k) ? String(vars[k]) : m));
  return out;
}
// tn picks the singular or plural source string, then translates it.
const tn = (n, one, many, vars = {}) => t(n === 1 ? one : many, { n, ...vars });
const locale = () => (i18n.lang === "zh" ? "zh-CN" : "en-US");

// applyStatic translates the HTML shell: data-i18n (text), data-i18n-placeholder
// and data-i18n-title hold the English source strings.
function applyStatic() {
  document.documentElement.lang = i18n.lang === "zh" ? "zh-CN" : "en";
  document.querySelectorAll("[data-i18n]").forEach((el) => (el.textContent = t(el.dataset.i18n)));
  document.querySelectorAll("[data-i18n-placeholder]").forEach((el) => (el.placeholder = t(el.dataset.i18nPlaceholder)));
  document.querySelectorAll("[data-i18n-title]").forEach((el) => (el.title = t(el.dataset.i18nTitle)));
}
